D={
910019:("A piece of cake","**A piece of cake** = muito fácil (idioma). Também: **a cinch**. O oposto: **tough** ou **hard**. Idiomas não se traduzem palavra por palavra.",[("This test is {{a piece of cake}}!","Esta prova é moleza!"),("The puzzle is {{easy}}.","O quebra-cabeça é fácil."),("That brain teaser is {{hard}}.","Esse desafio mental é difícil."),("It was {{tough}}.","Foi difícil.")],"O que significa a piece of cake?",["muito fácil","um pedaço","um bolo"],0,"Idioma: muito fácil."),
10180:("Posse com 's","**'s** mostra posse: *Mary's mother.* Para plural em **-s**: só o apóstrofo: *my parents' house*.",[("This is {{Mary's}} mother.","Esta é a mãe da Mary."),("That is {{my sister's}} room.","Aquele é o quarto da minha irmã."),("It's {{my parents'}} house.","É a casa dos meus pais."),("They look like their twin.","Eles se parecem com o gêmeo.")],"“O carro do meu pai”:",["my father's car","my fathers car","the car of father"],0,"'s para posse."),
70079:("Posse com 's","Ordem: **dono + 's + coisa**. *Tom's guardian, my stepmother's gift.* Em português é o contrário (“de”).",[("This is {{Tom's}} guardian.","Este é o responsável do Tom."),("It's {{my stepmother's}} gift.","É o presente da minha madrasta."),("Say hi to your parents.","Mande um oi aos seus pais."),("They spoil me!","Eles me mimam!")],"“O livro da Ana”:",["Ana's book","book Ana's","the Ana book"],0,"Ana's book."),
9811:("Como está o tempo?","Tempo: **What's the weather like?** Resposta: **It's sunny. It's rainy. It's cloudy.** Sempre com **it's**.",[("{{What's the weather like}}?","Como está o tempo?"),("{{It's sunny}}.","Está ensolarado."),("{{It's rainy}} today.","Está chuvoso hoje."),("{{It's cloudy}}.","Está nublado.")],"Como responder sobre o tempo?",["It's sunny.","He is sunny.","Is sunny it."],0,"It's + adjetivo."),
70081:("Frio e vento","**It's freezing!** = está congelando. **It's windy, chilly, snowy.** Para sentir: **I'm cold.** (não *it's cold* para pessoas).",[("{{It's freezing}}!","Está congelando!"),("{{It's windy}}.","Está ventando."),("{{It's snowy}} today.","Está nevando hoje."),("I'm cold.","Estou com frio.")],"O tempo, não a pessoa:",["It's cold.","I'm cold.","He cold."],0,"It's para o tempo."),
910020:("Also, too, as well","**Too** e **as well** vão no fim: *I like tea too.* **Also** vai antes do verbo: *I also like tea.* Os três = também.",[("I like tea {{too}}.","Eu também gosto de chá."),("She {{also}} likes coffee.","Ela também gosta de café."),("He's here {{as well}}.","Ele está aqui também."),("We're both happy.","Estamos os dois felizes.")],"Onde vai too?",["no fim","antes do verbo","no começo"],0,"Too = fim."),
9812:("Can you…?","Para pedir: **Can you call me? Can you text me?** Resposta: **Sure! / Sorry, I can't.** O verbo depois de *can you* fica sem -s.",[("{{Can you}} call me?","Você pode me ligar?"),("{{Sure}}!","Claro!"),("{{Can you}} text me?","Pode me mandar mensagem?"),("{{Sorry, I can't}}.","Desculpe, não posso.")],"Como pedir que respondam?",["Can you answer?","You can answer?","Answer can you?"],0,"Can you + verbo."),
70083:("Ao telefone","Ao telefone: **Hold the line.** = aguarde na linha. **Can I leave a message?** **Who's calling?**",[("{{Hold the line}}, please.","Aguarde na linha, por favor."),("{{Who's calling}}?","Quem está falando?"),("{{Can I leave a message}}?","Posso deixar um recado?"),("Check your voicemail.","Veja sua caixa postal.")],"“Aguarde na linha”:",["Hold the line.","Hold the phone, no.","Wait line."],0,"Hold the line."),
30042:("Enviar e responder","E-mail: **send, reply, delete**. *I send an email. I reply later. I delete spam.* Anexo: **attachment**.",[("I {{send}} an email.","Envio um e-mail."),("I {{reply}} later.","Respondo depois."),("I {{delete}} spam.","Apago o spam."),("Open the attachment.","Abra o anexo.")],"“Responder um e-mail”:",["reply","delete","send"],0,"Reply = responder."),
70084:("Get back to me","**Get back to me** = me responda depois. **I'll get back to you.** Na caixa: *draft, spam, inbox*.",[("{{Get back to me}} soon.","Me retorne em breve."),("{{I'll get back to you}}.","Eu retorno para você."),("This is spam.","Isto é spam."),("Open the draft.","Abra o rascunho.")],"O que significa get back to me?",["me retorne","volte para trás","me devolva"],0,"Me retorne."),
9813:("Elogios","Elogie: **I like your jacket! It's nice! It looks great!** Responda: **Thank you!**",[("{{I like}} your jacket!","Gosto da sua jaqueta!"),("{{It looks great}}!","Ficou ótima!"),("{{Thank you}}!","Obrigado!"),("It fits well.","Cai bem.")],"Resposta a um elogio:",["Thank you!","No!","Sorry."],0,"Thank you!"),
70085:("It suits you","**It suits you** = combina com você. **It fits** = serve (tamanho). *It's stylish.*",[("{{It suits you}}!","Combina com você!"),("{{It fits}} well.","Serve bem."),("It's very stylish.","É muito elegante."),("I'll buy it.","Vou comprar.")],"“Cai bem (tamanho)”:",["It fits.","It suits.","It matches size."],0,"Fits = tamanho."),
30043:("Spicy or sweet?","Preferências: **I like / I prefer / I don't like.** *I prefer spicy.* Depois de *prefer*: o que você prefere, direto.",[("I {{like}} spicy food.","Gosto de comida picante."),("She {{prefers}} sweet.","Ela prefere doce."),("I {{don't like}} salty snacks.","Não gosto de petiscos salgados."),("It's crunchy and tasty!","É crocante e gostoso!")],"“Prefiro doce”:",["I prefer sweet.","I do prefer sweets me.","Sweet prefer I."],0,"prefer + algo."),
9814:("Cozinhar: verbos","Verbos de cozinha: **cut, mix, add, boil.** No imperativo: *Cut the onion. Add garlic.* Sem sujeito.",[("{{Cut}} the onion.","Corte a cebola."),("{{Add}} garlic.","Adicione alho."),("{{Boil}} the noodles.","Ferva o macarrão."),("{{Mix}} the sauce.","Misture o molho.")],"“Ferva a água”:",["Boil the water.","You boil water.","Boiling water."],0,"Imperativo."),
910021:("Play sports","Com **play**: esportes com bola: *play soccer, play tennis.* **Play** também para jogos: *play cards*. Mas: **do** yoga, **go** swimming.",[("I {{play soccer}}.","Jogo futebol."),("She {{plays tennis}}.","Ela joga tênis."),("We {{play cards}}.","Jogamos cartas."),("He goes swimming.","Ele vai nadar.")],"“Jogar futebol”:",["play soccer","do soccer","go soccer"],0,"play + esporte."),
30044:("Refeições","Refeições: **breakfast, brunch, lunch, dinner.** Verbos: **have** ou **eat**. *We have brunch on Sundays.* Pedir: **order takeout**.",[("We {{have brunch}} on Sundays.","Tomamos brunch aos domingos."),("I {{order takeout}}.","Peço comida para viagem."),("They {{share}} appetizers.","Eles dividem aperitivos."),("The buffet is big.","O buffet é grande.")],"“Pedir comida para viagem”:",["order takeout","eat takeout","do takeout"],0,"order takeout."),
9815:("Some e any","**Some** em frases afirmativas; **any** em perguntas e negativas. *I have some milk. Do you have any? I don't have any.*",[("I have {{some}} juice.","Tenho um pouco de suco."),("Do you have {{any}} milk?","Você tem leite?"),("I don't have {{any}} eggs.","Não tenho ovos."),("We need some bread.","Precisamos de pão.")],"Complete: “I don't have ___ sugar.”",["some","any","a"],1,"Negativa: any."),
30045:("Pedir com educação","Em restaurante: **A table for two, please. Could I see the menu?** *Could* é mais educado que *can*.",[("{{A table for two}}, please.","Uma mesa para dois, por favor."),("{{Could I}} see the menu?","Poderia ver o cardápio?"),("{{What do you recommend}}?","O que você recomenda?"),("The check, please.","A conta, por favor.")],"Mais educado:",["Could I see the menu?","I see menu?","Give menu."],0,"Could I…?"),
9816:("Qual é seu trabalho?","**What do you do?** = qual é a sua profissão? Resposta: **I'm a** + profissão. *I'm a baker. I teach.* Também: verbo: **I work, I help**.",[("{{What do you do}}?","O que você faz?"),("{{I'm a}} dentist.","Sou dentista."),("{{I teach}} English.","Ensino inglês."),("She sings.","Ela canta.")],"Pergunta sobre a profissão:",["What do you do?","What do you work?","What you do for?"],0,"What do you do?"),
30046:("Where do you work?","Para o local de trabalho: **Where do you work?** — **I work at a hospital / in a factory / for a bank.** Preposições mudam.",[("{{Where do you work}}?","Onde você trabalha?"),("I work {{at}} a hospital.","Trabalho em um hospital."),("She works {{in}} a factory.","Ela trabalha em uma fábrica."),("He works {{for}} a bank.","Ele trabalha para um banco.")],"“Trabalho em um estúdio”:",["I work in a studio.","I work on studio.","I'm work studio."],0,"work in/at."),
9817:("Nacionalidades","Nacionalidade: **I'm Brazilian. She's Mexican.** Sempre com **maiúscula**. País: **I'm from Brazil.**",[("{{I'm}} Brazilian.","Sou brasileiro."),("She {{is}} Mexican.","Ela é mexicana."),("He is {{American}}.","Ele é americano."),("I come {{from}} France.","Venho da França.")],"“Sou italiano”:",["I'm Italian.","I'm italian.","I am a Italian."],0,"Maiúscula."),
30047:("Falar idiomas","Idiomas: **I speak English. Do you speak Spanish?** Resposta: **Yes, a little.** Idiomas com maiúscula.",[("I {{speak}} Portuguese.","Falo português."),("{{Do you speak}} Spanish?","Você fala espanhol?"),("Yes, {{a little}}.","Sim, um pouco."),("Can you repeat that?","Pode repetir?")],"Como perguntar se falam inglês?",["Do you speak English?","You are speak English?","Speak you English?"],0,"Do you speak…?"),
9818:("Gostar de fazer","Para hobbies: **I like + -ing.** *I like reading. She loves dancing.* **What do you do for fun?**",[("{{What do you do for fun}}?","O que você faz por diversão?"),("I {{like reading}}.","Gosto de ler."),("She {{loves dancing}}.","Ela adora dançar."),("We enjoy swimming.","Gostamos de nadar.")],"Complete: “I like ___.”",["cook","cooking","to cooking"],1,"like + -ing."),
910022:("Tempo livre","Com **watch / listen to**: **watch TV, watch a movie, listen to music.** Não se diz *listen music*.",[("I {{watch TV}}.","Assisto TV."),("She {{listens to}} music.","Ela escuta música."),("We {{watch}} cartoons.","Assistimos desenhos."),("He eats popcorn.","Ele come pipoca.")],"Qual está certa?",["listen music","listen to music","hear to music"],1,"listen to."),
80181:("He watches, she studies","Terceira pessoa: **+s** (*he works*), **+es** (*she watches, he goes, she washes*), consoante+y → **-ies** (*study → studies*).",[("He {{watches}} TV.","Ele assiste TV."),("She {{studies}} English.","Ela estuda inglês."),("He {{goes}} to work.","Ele vai ao trabalho."),("She {{has}} a cat.","Ela tem um gato.")],"Terceira pessoa de study:",["studys","studies","studyes"],1,"Consoante + y → -ies."),
80182:("Every day","**Every day, every morning** vão no começo ou no fim. *I wake up every morning.* Presente simples = hábito.",[("I {{wake up}} every morning.","Acordo toda manhã."),("{{Every day}} I take a shower.","Todo dia tomo banho."),("She has coffee every day.","Ela toma café todo dia."),("We brush our teeth.","Escovamos os dentes.")],"Presente simples serve para…",["hábitos","o agora","o passado"],0,"Hábitos."),
80183:("Always, usually, often","Frequência: **always** (100%), **usually**, **often**, **sometimes**, **rarely**, **never** (0%). Antes do verbo, depois do be.",[("I {{always}} brush my teeth.","Sempre escovo os dentes."),("She {{rarely}} eats candy.","Ela raramente come doces."),("I'm {{never}} late.","Nunca me atraso."),("We {{usually}} walk.","Normalmente caminhamos.")],"Qual é o mais frequente?",["always","sometimes","never"],0,"Always = sempre."),
80184:("Rotina de padeiro","Rotina de outra pessoa: **The baker makes bread. He opens the shop at six.** Terceira pessoa: verbo + **s**.",[("The baker {{makes}} bread.","O padeiro faz pão."),("He {{opens}} the shop at six.","Ele abre a loja às seis."),("The customers {{buy}} bread.","Os clientes compram pão."),("They like it warm.","Eles gostam quente.")],"Complete: “The baker ___ bread.”",["make","makes","making"],1,"3ª pessoa: -s."),
80185:("Imperativo","Imperativo: **verbo sozinho** (*Wash your face!*). Negativo: **Don't + verbo**. Gentil: **Please, wash…**",[("{{Wash}} your face!","Lave o rosto!"),("{{Dry}} your hands.","Seque as mãos."),("{{Don't touch}} the mirror.","Não toque no espelho."),("{{Please}}, use soap.","Por favor, use sabão.")],"“Não toque”:",["Don't touch.","No touch.","Not touching."],0,"Don't + verbo."),
80186:("Quantas vezes?","Frequência: **once a week** (1×), **twice a month** (2×), **three times a day**. Pergunta: **How often…?**",[("{{Once a week}}.","Uma vez por semana."),("{{Twice a month}}.","Duas vezes por mês."),("{{Three times}} a day.","Três vezes por dia."),("{{How often}} do you swim?","Com que frequência você nada?")],"“Duas vezes por semana”:",["twice a week","two time week","second week"],0,"twice a week."),
}
